const CONFIG = {
  maxInputLength: readPositiveInt('CALCULATOR_MAX_INPUT_LENGTH', 50),
  maxAbsValue: readPositiveNumber('CALCULATOR_MAX_ABS_VALUE', 1000000),
  decimalPlaces: readIntInRange('CALCULATOR_DECIMAL_PLACES', 0, 10, 10)
};

const MESSAGES = {
  empty: 'Повідомлення порожнє. Введіть приклад у форматі 12 + 7.',
  tooLong: 'Ввід занадто довгий. Максимум символів: ' + CONFIG.maxInputLength + '.',
  multiline: 'Введіть один приклад в одному повідомленні. Наприклад: 12 + 7',
  invalidFormat: 'Не вдалося розпізнати приклад. Використовуйте формат: 12 + 7',
  numberTooLarge: 'Числа занадто великі. Максимальне значення: ' + CONFIG.maxAbsValue + '.',
  divisionByZero: 'Ділити на нуль не можна. Спробуйте інший приклад.',
  invalidResult: 'Результат неможливо коректно порахувати. Спробуйте простіший приклад.'
};

const OPERATIONS = {
  '+': (left, right) => left + right,
  '-': (left, right) => left - right,
  '*': (left, right) => left * right,
  '×': (left, right) => left * right,
  '/': (left, right) => left / right,
  '÷': (left, right) => left / right
};

const input = getInput(msg);
const chatId = String(msg.payload?.chatId ?? 'unknown');

log('input_received', {
  input: input || '<empty>',
  inputLength: input.length,
  config: CONFIG
});

const parsed = parseExpression(input);
if (!parsed.ok) {
  return fail(parsed.reason, parsed.details);
}

const calculated = calculate(parsed.expression);
if (!calculated.ok) {
  return fail(calculated.reason, calculated.details);
}

msg.message = formatSuccessMessage(calculated.result);
log('calculation_succeeded', {
  expression: input,
  result: calculated.result
});

return msg;

function getInput(message) {
  const value = message.payload?.content ?? message.payload ?? '';
  return String(value).trim();
}

function parseExpression(value) {
  if (value.length === 0) {
    return invalid('empty');
  }

  if (value.length > CONFIG.maxInputLength) {
    return invalid('tooLong', { inputLength: value.length });
  }

  if (/[\r\n]/.test(value)) {
    return invalid('multiline');
  }

  const match = value.match(/^([+-]?\d+(?:[.,]\d+)?)\s*([+\-*/×÷])\s*([+-]?\d+(?:[.,]\d+)?)$/u);
  if (!match) {
    return invalid('invalidFormat');
  }

  const expression = {
    left: parseNumber(match[1]),
    operator: match[2],
    right: parseNumber(match[3])
  };

  if (!isAllowedNumber(expression.left) || !isAllowedNumber(expression.right)) {
    return invalid('numberTooLarge', {
      left: expression.left,
      right: expression.right
    });
  }

  if (isDivision(expression.operator) && expression.right === 0) {
    return invalid('divisionByZero');
  }

  return { ok: true, expression };
}

function calculate(expression) {
  const operation = OPERATIONS[expression.operator];
  const result = operation(expression.left, expression.right);

  if (!Number.isFinite(result)) {
    return invalid('invalidResult', { result });
  }

  return {
    ok: true,
    result: formatNumber(result)
  };
}

function parseNumber(value) {
  return Number(value.replace(',', '.'));
}

function isAllowedNumber(value) {
  return Number.isFinite(value) && Math.abs(value) <= CONFIG.maxAbsValue;
}

function isDivision(operator) {
  return operator === '/' || operator === '÷';
}

function formatNumber(value) {
  const rounded = Number(value.toFixed(CONFIG.decimalPlaces));
  return String(Object.is(rounded, -0) ? 0 : rounded);
}

function formatSuccessMessage(result) {
  return 'Результат: ' + result
    + '\n\nВведіть ще один приклад або натисніть кнопку Назад.';
}

function fail(reason, details = {}) {
  msg.message = MESSAGES[reason] || MESSAGES.invalidFormat;
  log('validation_failed', { reason, ...details }, 'warn');
  return msg;
}

function invalid(reason, details = {}) {
  return { ok: false, reason, details };
}

function log(event, details = {}, level = 'info') {
  writeLog('calc', event, chatId, details, level);
}

function writeLog(scope, event, chatId, details = {}, level = 'info') {
  const formatLogEvent = typeof global.get === 'function' ? global.get('formatLogEvent') : null;
  const entry = { level, scope, event, chatId, details };
  const line = typeof formatLogEvent === 'function'
    ? formatLogEvent(entry)
    : JSON.stringify({
      ts: new Date().toISOString(),
      step: scope + ':' + event,
      ...entry
    });

  if (level === 'warn' || level === 'error') {
    node.warn(line);
    return;
  }

  node.log(line);
}

function readPositiveInt(name, fallback) {
  const value = Number(env.get(name));
  return Number.isInteger(value) && value > 0 ? value : fallback;
}

function readPositiveNumber(name, fallback) {
  const value = Number(env.get(name));
  return Number.isFinite(value) && value > 0 ? value : fallback;
}

function readIntInRange(name, min, max, fallback) {
  const value = Number(env.get(name));
  return Number.isInteger(value) && value >= min && value <= max ? value : fallback;
}

const rawContent = msg.payload?.content ?? msg.payload ?? '';
const content = String(rawContent).trim();
const command = content.toLowerCase();
const chatId = String(msg.payload?.chatId ?? 'unknown');
const modes = flow.get('dialogModes') || {};

function saveModes() {
  flow.set('dialogModes', modes);
}

function clearMode() {
  delete modes[chatId];
  saveModes();
}

function setMode(mode) {
  modes[chatId] = mode;
  saveModes();
}

function log(event, details = {}) {
  writeLog('router', event, chatId, {
    content: content || '<empty>',
    mode: modes[chatId] || null,
    ...details
  });
}

const isMenuCommand = ['/start', '/menu', 'menu', 'back', 'назад', '⬅ назад'].includes(command);

if (isMenuCommand) {
  clearMode();
  log('main_menu');
  return [msg, null, null, null, null];
}

if (command === 'about') {
  clearMode();
  log('about');
  return [null, msg, null, null, null];
}

if (command === 'rates') {
  clearMode();
  log('rates');
  return [null, null, null, null, msg];
}

if (command === 'calc') {
  setMode('calculator');
  log('calculator_prompt');
  return [null, null, msg, null, null];
}

if (modes[chatId] === 'calculator') {
  log('calculator_input');
  return [null, null, null, msg, null];
}

clearMode();
log('fallback_menu');
return [msg, null, null, null, null];

function writeLog(scope, event, chatId, details = {}, level = 'info') {
  const formatLogEvent = typeof global.get === 'function' ? global.get('formatLogEvent') : null;
  const entry = { level, scope, event, chatId, details };
  const line = typeof formatLogEvent === 'function'
    ? formatLogEvent(entry)
    : JSON.stringify({
      ts: new Date().toISOString(),
      step: scope + ':' + event,
      ...entry
    });

  if (level === 'warn' || level === 'error') {
