}

const REQUIRED_CURRENCIES = ['USD', 'EUR'];
const ERROR_MESSAGE = 'Не вдалося отримати курс, спробуйте пізніше.';
const responsePayload = msg.payload;
const chatId = String(msg.nbu?.chatId ?? msg.originalMessage?.chatId ?? msg.chatId ?? 'unknown');

log('response_received', {
  statusCode: msg.statusCode ?? null,
  payloadType: Array.isArray(responsePayload) ? 'array' : typeof responsePayload
});

if (!isSuccessStatus(msg.statusCode)) {
  return fail('bad_status', { statusCode: msg.statusCode ?? null });
}

if (!Array.isArray(responsePayload)) {
  return fail('invalid_payload', { payloadType: typeof responsePayload });
}

const rates = REQUIRED_CURRENCIES.map(findRate).filter(Boolean);
if (rates.length !== REQUIRED_CURRENCIES.length) {
  return fail('missing_currency', {
    expected: REQUIRED_CURRENCIES,
    found: rates.map(rate => rate.cc)
  });
}

const invalidRate = rates.find(rate => !isValidRate(rate));
if (invalidRate) {
  return fail('invalid_rate_shape', { currency: invalidRate.cc });
}

restoreTelegramPayload();
msg.message = formatRatesMessage(rates);
log('rates_parsed', {
  currencies: rates.map(rate => ({
    cc: rate.cc,
    rate: rate.rate,
    exchangedate: rate.exchangedate
  }))
});

return msg;

function findRate(currencyCode) {
  return responsePayload.find(item => item?.cc === currencyCode);
}

function isSuccessStatus(statusCode) {
  return typeof statusCode === 'number' && statusCode >= 200 && statusCode < 300;
}

function isValidRate(rate) {
  return typeof rate.cc === 'string'
    && Number.isFinite(Number(rate.rate))
    && Number(rate.rate) > 0
    && typeof rate.exchangedate === 'string'
    && rate.exchangedate.trim().length > 0;
}

function formatRatesMessage(rates) {
  const date = rates[0].exchangedate;
  const lines = rates.map(rate => '1 ' + rate.cc + ' = ' + formatRate(rate.rate) + ' грн');

  return '💱 Курс валют НБУ'
    + '\nДата: ' + date
    + '\n\n' + lines.join('\n')
    + '\n\nДані отримано з відкритого API НБУ.';
}

function formatRate(value) {
  return Number(Number(value).toFixed(4))
    .toString()
    .replace('.', ',');
}

function fail(reason, details = {}) {
  restoreTelegramPayload();
  msg.message = '💱 Курс валют НБУ\n\n' + ERROR_MESSAGE;
  log('error', { reason, ...details }, 'warn');
  return msg;
}

function restoreTelegramPayload() {
  msg.payload = { chatId };
}

function log(event, details = {}, level = 'info') {
  writeLog('nbu', event, chatId, details, level);
}

function writeLog(scope, event, chatId, details = {}, level = 'info') {
  const formatLogEvent = typeof global.get === 'function' ? global.get('formatLogEvent') : null;
  const entry = { level, scope, event, chatId, details };
  const line = typeof formatLogEvent === 'function'
    ? formatLogEvent(entry)
    : JSON.stringify({
      ts: new Date().toISOString(),
      step: scope + ':' + event,
      ...entry
    });

  if (level === 'warn' || level === 'error') {
    node.warn(line);
    return;
  }

  node.log(line);
}

